const enc = new TextEncoder();
const authOverlay = document.getElementById("accessGate");
const ciInput = document.getElementById("ciAccess");
const accessBtn = document.getElementById("accessBtn");
const accessMsg = document.getElementById("accessMessage");
const logoutBtn = document.getElementById("logoutBtn");
let failedAttempts = 0;
let blockedUntil = 0;

function hex(buffer) {
  return Array.from(new Uint8Array(buffer))
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

async function deriveHash(value) {
  const baseKey = await crypto.subtle.importKey(
    "raw", enc.encode(value), "PBKDF2", false, ["deriveBits"]
  );
  const bits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt: enc.encode(PROYECTA_ACCESS.salt),
      iterations: PROYECTA_ACCESS.iterations,
      hash: "SHA-256"
    },
    baseKey,
    256
  );
  return hex(bits);
}

function showSite(role) {
  sessionStorage.setItem("proyectaAuth", role);
  document.body.classList.remove("access-locked");
  authOverlay.classList.add("hidden");
  if (logoutBtn) logoutBtn.classList.remove("hidden");
}

function lockSite() {
  document.body.classList.add("access-locked");
  authOverlay.classList.remove("hidden");
  if (logoutBtn) logoutBtn.classList.add("hidden");
}

async function authenticate() {
  const now = Date.now();
  if (now < blockedUntil) {
    const sec = Math.ceil((blockedUntil - now) / 1000);
    accessMsg.textContent = `Demasiados intentos. Espera ${sec} segundos.`;
    accessMsg.className = "access-message error";
    return;
  }

  const value = ciInput.value.replace(/\D/g, "");
  if (!value) {
    accessMsg.textContent = "Ingresa tu número de C.I. usando solo números.";
    accessMsg.className = "access-message error";
    return;
  }

  accessBtn.disabled = true;
  accessMsg.textContent = "Verificando...";
  accessMsg.className = "access-message";

  try {
    const h = await deriveHash(value);
    if (h === PROYECTA_ACCESS.teacherHash) {
      failedAttempts = 0;
      accessMsg.textContent = "Acceso docente autorizado.";
      accessMsg.className = "access-message ok";
      setTimeout(() => showSite("teacher"), 250);
      return;
    }

    if (PROYECTA_ACCESS.studentHashes.includes(h)) {
      failedAttempts = 0;
      accessMsg.textContent = "Acceso autorizado.";
      accessMsg.className = "access-message ok";
      setTimeout(() => showSite("student"), 250);
      return;
    }

    failedAttempts += 1;
    accessMsg.textContent = "C.I. no habilitado para este paralelo. Verifica el número e intenta nuevamente.";
    accessMsg.className = "access-message error";
    if (failedAttempts >= 5) {
      blockedUntil = Date.now() + 30000;
      failedAttempts = 0;
    }
  } catch (e) {
    console.error(e);
    accessMsg.textContent = "No fue posible verificar el acceso en este navegador.";
    accessMsg.className = "access-message error";
  } finally {
    accessBtn.disabled = false;
  }
}

accessBtn.addEventListener("click", authenticate);
ciInput.addEventListener("keydown", e => {
  if (e.key === "Enter") authenticate();
});
logoutBtn?.addEventListener("click", () => {
  sessionStorage.removeItem("proyectaAuth");
  ciInput.value = "";
  accessMsg.textContent = "";
  lockSite();
  ciInput.focus();
});

const existingRole = sessionStorage.getItem("proyectaAuth");
if (existingRole === "student" || existingRole === "teacher") {
  showSite(existingRole);
} else {
  lockSite();
  setTimeout(() => ciInput.focus(), 100);
}
